items.solution:
function theoreticalMM1(arrivalRate, serviceRate) {
  const rho = arrivalRate / serviceRate;
  const W = 1 / (serviceRate - arrivalRate);
  const L = rho / (1 - rho);
  return { rho, W, L };
}

