items.solution:
function mm1Metrics(serviceRate, arrivalRate) {
  const utilization = arrivalRate / serviceRate;
  const avgTimeInSystem = 1 / (serviceRate - arrivalRate);
  const avgNumberInSystem = utilization / (1 - utilization);
  return { utilization, avgTimeInSystem, avgNumberInSystem };
}

